	GetVersionPayload(context.Context, *GetVersionRequest) (*VersionPayload, error)
	DiffVersions(context.Context, *DiffVersionsRequest) (*DiffVersionsResponse, error)
	// CreateRelease starts a rollout. With dry_run it returns the plan and writes
	// nothing.
	CreateRelease(context.Context, *CreateReleaseRequest) (*CreateReleaseResponse, error)
	GetRelease(context.Context, *GetReleaseRequest) (*Release, error)
	ListReleases(context.Context, *ListReleasesRequest) (*ListReleasesResponse, error)
	PromoteRelease(context.Context, *PromoteReleaseRequest) (*Release, error)
	PauseRelease(context.Context, *ReleaseCommandRequest) (*Release, error)
	ResumeRelease(context.Context, *ReleaseCommandRequest) (*Release, error)
	RollbackRelease(context.Context, *ReleaseCommandRequest) (*Release, error)
	// KillSwitch immediately returns every ring of a target to its previous
	// known-good version and freezes the target. Break-glass, audited.
	KillSwitch(context.Context, *KillSwitchRequest) (*KillSwitchResponse, error)
	UnfreezeTarget(context.Context, *UnfreezeTargetRequest) (*Target, error)
	GetTarget(context.Context, *GetTargetRequest) (*Target, error)
	// GetRingProjection returns, per ring, the desired version and its signed
	// envelope. Used by sinks such as the Kubernetes controller.
	GetRingProjection(context.Context, *GetTargetRequest) (*RingProjection, error)
